import type { Lesson } from './lessons'

// PROJETS DE MODULE — Beau (26/10) : « à la fin d'un module, un projet ; quand c'est bon je passe au niveau suivant ; si j'échoue deux fois,
// un autre projet, jusqu'à ce que je maîtrise ; avec des indices et des rappels ; de vrais projets, pas une blague : c'est le parcours
// pour devenir ingénieur IA ». Chaque module a plusieurs variantes (A, B, C…) : même niveau, autre sujet.
// Le verdict vient du code (tests), pas d'un modèle ; le prof de l'élève commente en plus. Vérifiés par tests/projets.test.mjs.

type T = { fr: string; en: string }
const t = (fr: string, en: string): T => ({ fr, en })

interface Def {
  id: string; module: string; variante: string
  titre: T; brief: T; indices: T[]; rappels: string[]
  starter: string; solution: string; checks: string[]
}

const projet = (d: Def): Lesson => ({
  id: d.id, lang: 'py', niveau: 'projet', moduleProjet: { module: d.module, variante: d.variante },
  title: d.titre, explain: d.brief, example: '',
  task: t('Fais passer tous les tests du projet.', 'Make all the project’s tests pass.'),
  starter: d.starter, hint: d.indices[0], indices: d.indices, rappels: d.rappels, solution: d.solution, checks: d.checks,
})

const M1A = projet({
  id: 'pm-m1-a', module: 'm1', variante: 'A',
  titre: t('Gestionnaire de budget', 'Budget manager'),
  brief: t(
    "Tu construis le cœur d’une petite application de budget personnel, avec quatre fonctions qui travaillent ensemble.\nLe budget est un dictionnaire {catégorie: montant}.\n1) ajouter(budget, categorie, montant) : ajoute le montant à la catégorie (elle est créée si elle n’existe pas) et renvoie le budget. Un montant qui n’est pas strictement positif lève ValueError(\"montant invalide\").\n2) total(budget) : la somme de tous les montants.\n3) classement(budget) : la liste des couples (catégorie, montant), du plus gros montant au plus petit ; à montant égal, ordre alphabétique des catégories.\n4) rapport(budget) : un texte, une ligne par catégorie dans l’ordre du classement, au format « loyer: 500.00 (71.4%) » (montant à 2 décimales, part du total à 1 décimale), puis une dernière ligne « Total: 700.00 ». Pour un budget vide : « Total: 0.00 ».",
    "You build the core of a small personal-budget app, with four functions working together.\nThe budget is a dictionary {category: amount}.\n1) ajouter(budget, categorie, montant): adds the amount to the category (created if missing) and returns the budget. An amount that is not strictly positive raises ValueError(\"montant invalide\").\n2) total(budget): the sum of all amounts.\n3) classement(budget): the list of (category, amount) pairs, from the biggest amount to the smallest; on equal amounts, alphabetical order of categories.\n4) rapport(budget): a text, one line per category in ranking order, in the format “loyer: 500.00 (71.4%)” (amount with 2 decimals, share of the total with 1 decimal), then a last line “Total: 700.00”. For an empty budget: “Total: 0.00”.",
  ),
  indices: [
    t('Commence par ajouter et total : ce sont les plus courtes. Teste-les avec print avant de passer à la suite.', 'Start with ajouter and total: they are the shortest. Test them with print before moving on.'),
    t('Pour classement : sorted(budget.items(), key=...) avec une clé qui est un couple (−montant, catégorie).', 'For classement: sorted(budget.items(), key=...) with a key that is a pair (−amount, category).'),
    t('Pour rapport : une f-string par ligne, f"{c}: {m:.2f} ({m / t * 100:.1f}%)", puis "\\n".join(lignes). Pense au budget vide (division par zéro).', 'For rapport: one f-string per line, f"{c}: {m:.2f} ({m / t * 100:.1f}%)", then "\\n".join(lines). Think of the empty budget (division by zero).'),
  ],
  rappels: ['py-dict', 'py-sortkey', 'py-str', 'py-loops'],
  starter: 'def ajouter(budget, categorie, montant):\n    pass\n\ndef total(budget):\n    pass\n\ndef classement(budget):\n    pass\n\ndef rapport(budget):\n    pass\n',
  solution: 'def ajouter(budget, categorie, montant):\n    if montant <= 0:\n        raise ValueError("montant invalide")\n    budget[categorie] = budget.get(categorie, 0) + montant\n    return budget\n\ndef total(budget):\n    return sum(budget.values())\n\ndef classement(budget):\n    return sorted(budget.items(), key=lambda kv: (-kv[1], kv[0]))\n\ndef rapport(budget):\n    t = total(budget)\n    lignes = []\n    for c, m in classement(budget):\n        lignes.append(f"{c}: {m:.2f} ({m / t * 100:.1f}%)")\n    lignes.append(f"Total: {t:.2f}")\n    return "\\n".join(lignes)',
  checks: [
    'ajouter(ajouter({}, "loyer", 500), "courses", 120.5) == {"loyer": 500, "courses": 120.5}',
    '(lambda b: (ajouter(b, "x", 2), ajouter(b, "x", 3), b)[2])({}) == {"x": 5}',
    '__raises(lambda: ajouter({}, "x", 0), ValueError)',
    '__raises(lambda: ajouter({}, "x", -5), ValueError)',
    'total({"loyer": 500, "courses": 200.0}) == 700.0 and total({}) == 0',
    'classement({"loyer": 500, "courses": 200.0}) == [("loyer", 500), ("courses", 200.0)]',
    'classement({"b": 10, "a": 10, "c": 30}) == [("c", 30), ("a", 10), ("b", 10)]',
    'rapport({"loyer": 500, "courses": 200.0}) == "loyer: 500.00 (71.4%)\\ncourses: 200.00 (28.6%)\\nTotal: 700.00"',
    'rapport({}) == "Total: 0.00"',
  ],
})

const M1B = projet({
  id: 'pm-m1-b', module: 'm1', variante: 'B',
  titre: t('Analyseur de texte', 'Text analyser'),
  brief: t(
    "Tu écris l’outil d’analyse d’un texte : le point de départ de tout traitement du langage.\n1) mots(texte) : la liste des mots, en minuscules. Un mot est une suite de LETTRES (accents compris) ; tout le reste (espace, ponctuation, apostrophe, chiffre) sépare les mots. « L’été, c’est beau ! » donne ['l', 'été', 'c', 'est', 'beau'].\n2) frequences(texte) : un dictionnaire {mot: nombre d’apparitions}.\n3) top(texte, n) : les n mots les plus fréquents, sous forme de couples (mot, nombre), du plus fréquent au moins fréquent ; à égalité, ordre alphabétique.\n4) plus_long(texte) : le mot le plus long (à égalité : le premier par ordre alphabétique) ; « » si le texte n’a aucun mot.\n5) rapport(texte) : un dictionnaire avec les clés 'mots' (nombre total de mots), 'uniques' (nombre de mots différents), 'plus_long' et 'top3'.",
    "You write a text-analysis tool: the starting point of all language processing.\n1) mots(texte): the list of words, in lowercase. A word is a run of LETTERS (accents included); everything else (space, punctuation, apostrophe, digit) separates words. “L’été, c’est beau !” gives ['l', 'été', 'c', 'est', 'beau'].\n2) frequences(texte): a dictionary {word: number of occurrences}.\n3) top(texte, n): the n most frequent words, as (word, count) pairs, most frequent first; on a tie, alphabetical order.\n4) plus_long(texte): the longest word (on a tie: the first alphabetically); “” if the text has no word.\n5) rapport(texte): a dictionary with keys 'mots' (total number of words), 'uniques' (number of different words), 'plus_long' and 'top3'.",
  ),
  indices: [
    t('mots est la base : parcours les lettres du texte en minuscules ; tant que c’est une lettre (ch.isalpha()), construis le mot ; sinon, termine-le.', 'mots is the base: walk through the lowercase letters; while it is a letter (ch.isalpha()), build the word; otherwise, end it.'),
    t('N’oublie pas le dernier mot si le texte ne finit pas par un séparateur.', 'Do not forget the last word if the text does not end with a separator.'),
    t('top et plus_long se règlent avec sorted(..., key=lambda ...) : une clé (−nombre, mot) pour top, (−longueur, mot) pour plus_long.', 'top and plus_long are handled with sorted(..., key=lambda ...): a key (−count, word) for top, (−length, word) for plus_long.'),
  ],
  rappels: ['py-text', 'py-dict', 'py-sortkey', 'py-loops'],
  starter: 'def mots(texte):\n    pass\n\ndef frequences(texte):\n    pass\n\ndef top(texte, n):\n    pass\n\ndef plus_long(texte):\n    pass\n\ndef rapport(texte):\n    pass\n',
  solution: 'def mots(texte):\n    resultat = []\n    mot = ""\n    for ch in texte.lower():\n        if ch.isalpha():\n            mot += ch\n        elif mot:\n            resultat.append(mot)\n            mot = ""\n    if mot:\n        resultat.append(mot)\n    return resultat\n\ndef frequences(texte):\n    d = {}\n    for m in mots(texte):\n        d[m] = d.get(m, 0) + 1\n    return d\n\ndef top(texte, n):\n    return sorted(frequences(texte).items(), key=lambda kv: (-kv[1], kv[0]))[:n]\n\ndef plus_long(texte):\n    liste = mots(texte)\n    if not liste:\n        return ""\n    return sorted(liste, key=lambda m: (-len(m), m))[0]\n\ndef rapport(texte):\n    liste = mots(texte)\n    return {"mots": len(liste), "uniques": len(set(liste)), "plus_long": plus_long(texte), "top3": top(texte, 3)}',
  checks: [
    'mots("Le chat et le chien. Le chat dort !") == ["le", "chat", "et", "le", "chien", "le", "chat", "dort"]',
    'mots("L’été, c’est beau !") == ["l", "été", "c", "est", "beau"]',
    'mots("") == [] and mots("123 !!") == []',
    'frequences("a b a c a b") == {"a": 3, "b": 2, "c": 1}',
    'top("Le chat et le chien. Le chat dort !", 2) == [("le", 3), ("chat", 2)]',
    'top("b a b a c", 3) == [("a", 2), ("b", 2), ("c", 1)]',
    'plus_long("Le chat et le chien. Le chat dort !") == "chien" and plus_long("") == ""',
    'plus_long("un deux six") == "deux"',
    'rapport("Le chat et le chien. Le chat dort !") == {"mots": 8, "uniques": 5, "plus_long": "chien", "top3": [("le", 3), ("chat", 2), ("chien", 1)]}',
  ],
})

const M1C = projet({
  id: 'pm-m1-c', module: 'm1', variante: 'C',
  titre: t('Carnet de notes d’une classe', 'Class gradebook'),
  brief: t(
    "Tu construis le calcul d’un bulletin de classe. Les élèves sont un dictionnaire {nom: [notes]}.\n1) moyenne(notes) : la moyenne arrondie à 2 décimales ; 0.0 si la liste est vide.\n2) mention(m) : « Très bien » à partir de 16, « Bien » à partir de 14, « Assez bien » à partir de 12, « Passable » à partir de 10, sinon « Insuffisant ».\n3) mediane(valeurs) : la médiane (la valeur du milieu ; pour un nombre pair de valeurs, la moyenne des deux du milieu) ; 0.0 si la liste est vide.\n4) bulletin(eleves) : une liste de dictionnaires {'nom', 'moyenne', 'mention'}, du meilleur au moins bon ; à égalité, ordre alphabétique des noms.\n5) stats_classe(eleves) : un dictionnaire avec 'moyenne_classe' (moyenne des moyennes, 2 décimales), 'mediane' (médiane des moyennes, 2 décimales), 'meilleur' (le nom du premier du bulletin) et 'admis' (le nombre d’élèves à 10 ou plus).",
    "You build the calculation of a class report. Students are a dictionary {name: [grades]}.\n1) moyenne(notes): the average rounded to 2 decimals; 0.0 if the list is empty.\n2) mention(m): “Très bien” from 16, “Bien” from 14, “Assez bien” from 12, “Passable” from 10, otherwise “Insuffisant”.\n3) mediane(valeurs): the median (the middle value; for an even number of values, the average of the two middle ones); 0.0 if the list is empty.\n4) bulletin(eleves): a list of dictionaries {'nom', 'moyenne', 'mention'}, best first; on a tie, alphabetical order of names.\n5) stats_classe(eleves): a dictionary with 'moyenne_classe' (average of averages, 2 decimals), 'mediane' (median of averages, 2 decimals), 'meilleur' (name of the first in the report) and 'admis' (number of students at 10 or more).",
  ),
  indices: [
    t('Commence par moyenne et mention : de petites fonctions, faciles à tester. Les autres s’appuient dessus.', 'Start with moyenne and mention: small functions, easy to test. The others build on them.'),
    t('mediane : trie la liste, puis regarde si le nombre de valeurs est pair ou impair (n % 2).', 'mediane: sort the list, then see whether the number of values is even or odd (n % 2).'),
    t('bulletin : construis la liste de dictionnaires, puis sorted(..., key=lambda d: (-d["moyenne"], d["nom"])). stats_classe réutilise bulletin.', 'bulletin: build the list of dictionaries, then sorted(..., key=lambda d: (-d["moyenne"], d["nom"])). stats_classe reuses bulletin.'),
  ],
  rappels: ['py-lists', 'py-dict', 'py-cond', 'py-sortkey'],
  starter: 'def moyenne(notes):\n    pass\n\ndef mention(m):\n    pass\n\ndef mediane(valeurs):\n    pass\n\ndef bulletin(eleves):\n    pass\n\ndef stats_classe(eleves):\n    pass\n',
  solution: 'def moyenne(notes):\n    return round(sum(notes) / len(notes), 2) if notes else 0.0\n\ndef mention(m):\n    if m >= 16:\n        return "Très bien"\n    if m >= 14:\n        return "Bien"\n    if m >= 12:\n        return "Assez bien"\n    if m >= 10:\n        return "Passable"\n    return "Insuffisant"\n\ndef mediane(valeurs):\n    s = sorted(valeurs)\n    n = len(s)\n    if n == 0:\n        return 0.0\n    if n % 2:\n        return float(s[n // 2])\n    return (s[n // 2 - 1] + s[n // 2]) / 2\n\ndef bulletin(eleves):\n    liste = []\n    for nom, notes in eleves.items():\n        m = moyenne(notes)\n        liste.append({"nom": nom, "moyenne": m, "mention": mention(m)})\n    return sorted(liste, key=lambda d: (-d["moyenne"], d["nom"]))\n\ndef stats_classe(eleves):\n    b = bulletin(eleves)\n    ms = [d["moyenne"] for d in b]\n    return {"moyenne_classe": round(sum(ms) / len(ms), 2), "mediane": round(mediane(ms), 2), "meilleur": b[0]["nom"], "admis": sum(1 for m in ms if m >= 10)}',
  checks: [
    'moyenne([15, 17, 16]) == 16.0 and moyenne([8, 12, 9]) == 9.67 and moyenne([]) == 0.0',
    '[mention(x) for x in (16, 14, 12, 10, 9.99)] == ["Très bien", "Bien", "Assez bien", "Passable", "Insuffisant"]',
    'mediane([1, 3, 2]) == 2.0 and mediane([1, 2, 3, 4]) == 2.5 and mediane([]) == 0.0',
    'bulletin({"Zoé": [15, 17, 16], "Amir": [8, 12, 9], "Lina": [12, 14, 13], "Paul": [9, 11, 10]}) == [{"nom": "Zoé", "moyenne": 16.0, "mention": "Très bien"}, {"nom": "Lina", "moyenne": 13.0, "mention": "Assez bien"}, {"nom": "Paul", "moyenne": 10.0, "mention": "Passable"}, {"nom": "Amir", "moyenne": 9.67, "mention": "Insuffisant"}]',
    '[d["nom"] for d in bulletin({"b": [10], "a": [10]})] == ["a", "b"]',
    'stats_classe({"Zoé": [15, 17, 16], "Amir": [8, 12, 9], "Lina": [12, 14, 13], "Paul": [9, 11, 10]}) == {"moyenne_classe": 12.17, "mediane": 11.5, "meilleur": "Zoé", "admis": 3}',
  ],
})


