/** Projets d'étape : proposés au milieu d'un module, juste après la leçon `apres` (Beau, 26/10 : un projet après les boucles, un autre après les listes, puis celui qui regroupe tout). */
export const JALONS: { id: string; apres: string }[] = [
  { id: 'm1-j1', apres: 'py-loops' },
  { id: 'm1-j2', apres: 'py-dict' },
]

// ───────── État de l'élève : où il en est dans les projets d'un module (gardé sur son appareil) ─────────
export interface EtatProjet {
  /** Numéro de la variante en cours (0 = A, 1 = B…). */
  v: number
  /** Échecs de la variante en cours : après deux, un autre projet est proposé. */
  echecs: number
  /** Indices dévoilés par projet (id → nombre). */
  vus: Record<string, number>
  /** Le code de chaque projet (id → code). */
  codes: Record<string, string>
}
const CLE = (m: string) => 'learn:pm:' + m
export const ECHECS_MAX = 2
export function lireEtat(module: string): EtatProjet {
  try {
    const o = JSON.parse(localStorage.getItem(CLE(module)) ?? '{}')
    return { v: Number.isInteger(o.v) && o.v >= 0 ? o.v : 0, echecs: Number.isInteger(o.echecs) ? o.echecs : 0, vus: o.vus && typeof o.vus === 'object' ? o.vus : {}, codes: o.codes && typeof o.codes === 'object' ? o.codes : {} }
  } catch { return { v: 0, echecs: 0, vus: {}, codes: {} } }
}
export function ecrireEtat(module: string, e: EtatProjet) { try { localStorage.setItem(CLE(module), JSON.stringify(e)) } catch { /* ignoré */ } }
/** Le projet du module est réussi (tests passés) : la date, ou rien. */
export const projetReussi = (module: string) => { try { return localStorage.getItem('learn:projetValide:' + module) || '' } catch { return '' } }
export const marquerReussi = (module: string) => { try { localStorage.setItem('learn:projetValide:' + module, new Date().toISOString().slice(0, 10)) } catch { /* ignoré */ } }
/** Faut-il passer par le projet avant de quitter ce module ? (il existe, et il n'est pas encore réussi) */
export const projetEnAttente = (module: string) => !!PROJETS[module] && !projetReussi(module)
